using System.Security.Claims; using Microsoft.AspNetCore.Authentication; using Microsoft.AspNetCore.Authentication.Cookies; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using System.Net.Http.Json;
namespace SportRace.Web.Pages.Account;
public class LoginModel:PageModel {private readonly IHttpClientFactory _factory;[BindProperty]public LoginInput Input{get;set;}=new();public LoginModel(IHttpClientFactory factory)=>_factory=factory;public async Task<IActionResult> OnPostAsync(){var r=await _factory.CreateClient("SportRaceApi1").PostAsJsonAsync("api/users/login",Input);if(!r.IsSuccessStatusCode){ModelState.AddModelError("","Невалиден e-mail или парола.");return Page();}var u=await r.Content.ReadFromJsonAsync<LoginResult>();var claims=new[]{new Claim(ClaimTypes.NameIdentifier,u!.Id.ToString()),new Claim(ClaimTypes.Name,$"{u.FirstName} {u.LastName}"),new Claim(ClaimTypes.Email,u.Email),new Claim(ClaimTypes.Role,u.Role)};await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new ClaimsPrincipal(new ClaimsIdentity(claims,CookieAuthenticationDefaults.AuthenticationScheme)));return RedirectToPage("/Index");}public class LoginInput{public string Email{get;set;}="";public string Password{get;set;}="";}public class LoginResult{public int Id{get;set;}public string FirstName{get;set;}="";public string LastName{get;set;}="";public string Email{get;set;}="";public string Role{get;set;}="";}}
